from pysat.solvers import Glucose4
from pysat.formula import CNF
from itertools import product

n = 12
# Variables: v[i][j][k] = 1 iff x[i][j] = k
def var(i,j,k):
    return i*n*n + j*n + k + 1

clauses = []
# Each cell has exactly one value
for i in range(n):
    for j in range(n):
        clauses.append([var(i,j,k) for k in range(n)])
        for k1 in range(n):
            for k2 in range(k1+1,n):
                clauses.append([-var(i,j,k1), -var(i,j,k2)])

# Latin: each row has each value once
for i in range(n):
    for k in range(n):
        clauses.append([var(i,j,k) for j in range(n)])
        for j1 in range(n):
            for j2 in range(j1+1,n):
                clauses.append([-var(i,j1,k), -var(i,j2,k)])

for j in range(n):
    for k in range(n):
        clauses.append([var(i,j,k) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1+1,n):
                clauses.append([-var(i1,j,k), -var(i2,j,k)])

# Idempotent
for i in range(n):
    clauses.append([var(i,i,i)])

# QG3: x[x[i][j]][x[j][i]] = i
# For all i,j,a,b: if x[i][j]=a and x[j][i]=b then x[a][b]=i
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                clauses.append([-var(i,j,a), -var(j,i,b), var(a,b,i)])

s = Glucose4()
for c in clauses:
    s.add_clause(c)
print("solving...")
print(s.solve())
m = s.get_model()
grid = [[0]*n for _ in range(n)]
mset = set(x for x in m if x>0)
for i in range(n):
    for j in range(n):
        for k in range(n):
            if var(i,j,k) in mset:
                grid[i][j] = k
for row in grid:
    print(row)

# verify
for i in range(n):
    assert set(grid[i])==set(range(n))
    assert set(grid[r][i] for r in range(n))==set(range(n))
    assert grid[i][i]==i
for i in range(n):
    for j in range(n):
        a=grid[i][j]; b=grid[j][i]
        assert grid[a][b]==i
print("OK")
flat = [grid[i][j] for i in range(n) for j in range(n)]
print(flat)
